drop policy if exists "permission updates moderation appeals" on public.moderation_appeals; create policy "permission updates moderation appeals" on public.moderation_appeals for update to authenticated using ((select private.has_permission('discipline.review'))) with check ((select private.has_permission('discipline.review')));
drop policy if exists "permission writes moderation reviews" on public.moderation_reviews; create policy "permission writes moderation reviews" on public.moderation_reviews for insert to authenticated with check ((reviewer_id=(select auth.uid())) and (select private.has_permission('discipline.review')));
